Add-Type -AssemblyName System.IO.Compression.FileSystem
$files = 'baston1.2','axe','valki','spada','sscudo','sscudo adnto','baston1','baston2','baston3'
$outDir = "$env:TEMP\pxo_previews"; New-Item -ItemType Directory -Force $outDir | Out-Null
foreach ($f in $files) {
  $path = "C:\Users\Romelt\Desktop\$f.pxo"
  $z = [IO.Compression.ZipFile]::OpenRead($path)
  $json = (New-Object IO.StreamReader($z.GetEntry('data.json').Open())).ReadToEnd() | ConvertFrom-Json
  $pal = ($json.palettes | % { $_.PSObject.Properties.Name }) -join ','
  $colors = @{}; $alphas = @{}; $opaque = 0
  $minX=99999;$minY=99999;$maxX=-1;$maxY=-1
  $fi = 0
  foreach ($fr in $json.frames) {
    $fi++; $li = 0
    foreach ($cel in $fr.cels) {
      $li++
      $entry = $z.GetEntry("image_data/frames/$fi/layer_$li")
      if (-not $entry -or $entry.Length -eq 0) { continue }
      if ($cel.image_size -match '(\d+), (\d+)') { $w=[int]$matches[1]; $h=[int]$matches[2] } else { $w=$json.size_x; $h=$json.size_y }
      $ox=0;$oy=0; if ($cel.offset -match '\((-?\d+), (-?\d+)\)') { $ox=[int]$matches[1]; $oy=[int]$matches[2] }
      $ms = New-Object IO.MemoryStream; $entry.Open().CopyTo($ms); $b = $ms.ToArray()
      for ($i=0; $i -lt $b.Length; $i+=4) {
        $a = $b[$i+3]; if ($a -eq 0) { continue }
        $opaque++
        $alphas[$a] = 1
        $colors[[BitConverter]::ToUInt32($b,$i)] = 1
        $p = $i/4; $x = $p % $w + $ox; $y = [Math]::Floor($p / $w) + $oy
        if ($x -lt $minX){$minX=$x}; if ($x -gt $maxX){$maxX=$x}; if ($y -lt $minY){$minY=$y}; if ($y -gt $maxY){$maxY=$y}
      }
    }
  }
  $prev = $z.GetEntry('preview.png')
  if ($prev) { $fs=[IO.File]::Create("$outDir\$f.png"); $prev.Open().CopyTo($fs); $fs.Close() }
  $z.Dispose()
  "{0,-14} canvas={1}x{2} frames={3} layers={4} bbox={5}x{6} px={7} colores={8} alphas={9} paleta={10}" -f $f,$json.size_x,$json.size_y,$json.frames.Count,$json.layers.Count,($maxX-$minX+1),($maxY-$minY+1),$opaque,$colors.Count,(($alphas.Keys | sort) -join '/'),$pal
}

Add-Type -AssemblyName System.IO.Compression.FileSystem
$files = 'baston1.2','axe','valki','spada','sscudo','sscudo adnto','baston1','baston2','baston3'
$all = @{}
foreach ($f in $files) {
  $z = [IO.Compression.ZipFile]::OpenRead("C:\Users\Romelt\Desktop\$f.pxo")
  $local = @{}
  foreach ($e in $z.Entries | ? { $_.FullName -match '/layer_\d+$' -and $_.Length -gt 0 }) {
    $ms = New-Object IO.MemoryStream; $e.Open().CopyTo($ms); $b = $ms.ToArray()
    for ($i=0; $i -lt $b.Length; $i+=4) {
      if ($b[$i+3] -eq 0) { continue }
      $hex = '#{0:X2}{1:X2}{2:X2}' -f $b[$i],$b[$i+1],$b[$i+2]
      $local[$hex]++
    }
  }
  $z.Dispose()
  foreach ($k in $local.Keys) { if (-not $all[$k]) { $all[$k] = @() }; $all[$k] += $f }
  "$f : " + (($local.GetEnumerator() | sort Value -Descending | % { "$($_.Key)($($_.Value))" }) -join ' ')
}
"TOTAL unicos: $($all.Count)"
$all.GetEnumerator() | sort { $_.Value.Count } -Descending | % { "$($_.Key) -> $($_.Value -join ',')" }
